input.proposed_solution:
Catch errors inside track() and increment a dropped-events counter exposed as droppedEvents(); no rethrow, no per-error log. Added a test with a failing transport.

Patch (already applied in the repository snapshot):
```diff
--- a/src/telemetry.js
+++ b/src/telemetry.js
@@ -2,12 +2,24 @@

 /** @typedef {{ send: (event: object) => Promise<void> }} Transport */

-/** @param {Transport} transport */
+/**
+ * Telemetry is best-effort by product decision: a failed analytics send must never fail
+ * or slow down the user's request. Failures are counted (exported as a metric) instead of thrown.
+ * @param {Transport} transport
+ */
 export function createTelemetry(transport) {
+  let dropped = 0;
   return {
     /** @param {object} event */
     async track(event) {
-      await transport.send(event);
+      try {
+        await transport.send(event);
+      } catch {
+        dropped++;
+      }
+    },
+    droppedEvents() {
+      return dropped;
     },
   };
 }
--- a/test/telemetry.test.js
+++ b/test/telemetry.test.js
@@ -8,3 +8,10 @@
   await t.track({ type: "x" });
   assert.equal(sent.length, 1);
 });
+
+test("a failing transport does not fail the request and is counted", async () => {
+  const { placeOrder } = await import("../src/orders.js");
+  const t = createTelemetry({ send: async () => { throw new Error("analytics down"); } });
+  assert.deepEqual(await placeOrder(t, { id: "o1" }), { ok: true, id: "o1" });
+  assert.equal(t.droppedEvents(), 1);
+});
```
